import crypto from 'node:crypto';

export interface VerifySignatureParams {
  publicKeySpkiBase64: string;
  payload: string;
  signatureHex: string;
}

/**
 * Verifies ECDSA P-256 SHA-256 signature generated by browser WebCrypto.
 * WebCrypto signs with IEEE P1363 raw (r || s, 64 bytes) encoding.
 */
export function verifyP256Signature({
  publicKeySpkiBase64,
  payload,
  signatureHex,
}: VerifySignatureParams): boolean {
  try {
    if (!publicKeySpkiBase64 || !payload || !signatureHex) {
      return false;
    }

    const cleanSpki = publicKeySpkiBase64.replace(/[\r\n\s]/g, '');
    const pem = `-----BEGIN PUBLIC KEY-----\n${cleanSpki}\n-----END PUBLIC KEY-----`;

    const verifier = crypto.createVerify('SHA256');
    verifier.update(payload);
    verifier.end();

    const sigBuffer = Buffer.from(signatureHex, 'hex');

    // Try ieee-p1363 first (standard for WebCrypto ECDSA)
    try {
      const valid = verifier.verify(
        { key: pem, dsaEncoding: 'ieee-p1363' },
        sigBuffer
      );
      if (valid) return true;
    } catch {
      // fallback to der
    }

    // Secondary attempt with der encoding
    const verifierDer = crypto.createVerify('SHA256');
    verifierDer.update(payload);
    verifierDer.end();
    return verifierDer.verify(pem, sigBuffer);
  } catch (err) {
    console.warn('[Crypto] Signature verification error:', err);
    return false;
  }
}
